package rules

import (
	"math/rand/v2"
	"regexp"
	"slices"
	"strings"
	"testing"
)

// The docblock hot paths scan bytes instead of running these regexes; each
// scanner must agree with its regex on every input.

var regexpFreePieces = []string{
	"", "*", "**", "@", "@var", "@param-", "/", "/**", "*/", " ", "\t", "\n", "\r", "\r\n", "\v", "\f",
	"a", "an", "A", "An", "the", "THE", "s", "es", "gets", "x_1", "-", ".", "!", "(", "<<<", "EOT", "'EOT'",
	"class", "Class", "trait", "interface", "constructor", "Constructor", "// TODO: Implement foo() method.",
	"// TODO: Change the autogenerated stub", "Doctrine", "doctrine", "This class was generated by the Doctrine ORM. Add your own custom",
	"repository methods below.", "getFooBar", "fooBAR", "aB", " ", " ", "\u0085", "\xff", "K", "ſ", "é",
}

func regexpFreeInputs(n int) []string {
	r := rand.New(rand.NewPCG(1, 2))
	inputs := make([]string, 0, n+len(regexpFreePieces))
	inputs = append(inputs, regexpFreePieces...)
	for range n {
		var b strings.Builder
		for range r.IntN(12) {
			b.WriteString(regexpFreePieces[r.IntN(len(regexpFreePieces))])
		}
		inputs = append(inputs, b.String())
	}
	return inputs
}

func TestRegexpFreeScannersMatchRegexps(t *testing.T) {
	var (
		docLineSplit  = regexp.MustCompile(`[^\n\r]+(?:\r\n|\r|\n)*`)
		docLineTag    = regexp.MustCompile(`\*\s*@`)
		docLineUseful = regexp.MustCompile(`\*\s*\S+`)
		phpDocUseful  = regexp.MustCompile(`\*[` + pcreSpaceClass + `]*[^` + pcreSpaceClass + `]`)
		phpDocTag     = regexp.MustCompile(`\*[` + pcreSpaceClass + `]*@`)
		tagNameRegexp = regexp.MustCompile(`@[a-zA-Z0-9_-]+`)
		articles      = regexp.MustCompile(`(?i)\b(?:a|an|the)\b`)
		thirdPersonS  = regexp.MustCompile(`^([\s*]*\w+?)s\b`)
		spaceNl       = regexp.MustCompile(`[\s\n]+`)
	)
	tagNameByRegexp := func(line string) string {
		for _, m := range tagNameRegexp.FindAllStringIndex(line, -1) {
			if r, _ := pcreRuneAt(line, m[1]); m[1] == len(line) || pcreIsSpace(r) {
				return line[m[0]+1 : m[1]]
			}
		}
		return "other"
	}
	wordsByRegexp := func(value string) []string {
		spaced := camelBoundaryRe.ReplaceAllString(value, "$1 $2")
		return wordRe.FindAllString(strings.ToLower(spaced), -1)
	}

	for _, in := range regexpFreeInputs(200_000) {
		check := func(name string, got, want any) {
			t.Helper()
			if !equalAny(got, want) {
				t.Fatalf("%s(%q) = %q, regexp gives %q", name, in, got, want)
			}
		}
		check("splitDocLines", splitDocLines(in), docLineSplit.FindAllString(in, -1))
		check("lineContainsTag", lineContainsTag(in), docLineTag.MatchString(in))
		check("useful", starThenSpaces(in, func(j int) bool { return j < len(in) }), docLineUseful.MatchString(in))
		line := &phpDocLine{content: in}
		check("containsATag", line.containsATag(), phpDocTag.MatchString(in))
		check("pcreUseful", pcreStarThenSpaces(in, func(j int) bool { return j < len(in) }), phpDocUseful.MatchString(in))
		check("phpDocTagName", phpDocTagName(in), tagNameByRegexp(in))
		check("resolveWords", resolveWords(in), wordsByRegexp(in))
		check("removeArticles", removeArticles(in), articles.ReplaceAllString(in, ""))
		check("dropThirdPersonS", dropThirdPersonS(in), thirdPersonS.ReplaceAllString(in, "$1"))
		check("removeRESpaces", removeRESpaces(in), spaceNl.ReplaceAllString(in, ""))
		for _, className := range []string{"", "Foo"} {
			check("clearUselessDocContent", clearUselessDocContent(in, className), clearUselessDocContentByRegexp(in, className))
		}
	}
}

// clearUselessDocContentByRegexp is clearUselessDocContent before its regexes
// got prefilters.
func clearUselessDocContentByRegexp(docContent, className string) string {
	lines := strings.Split(docContent, "\n")
	kept := make([]string, 0, len(lines))
	inHeredoc := false
	var heredocLabel string
	for _, line := range lines {
		if inHeredoc {
			kept = append(kept, line)
			if isHeredocCloser(line, heredocLabel) {
				inHeredoc = false
			}
			continue
		}
		if match := heredocOpenerRegex.FindStringSubmatch(line); match != nil {
			heredocLabel = match[1]
			inHeredoc = true
			kept = append(kept, line)
			continue
		}
		if className != "" && strings.Trim(line, "* ") == className {
			continue
		}
		for _, re := range uselessCommentRegexes {
			line = re.ReplaceAllString(line, "")
		}
		if line == "" {
			continue
		}
		kept = append(kept, line)
	}
	if len(kept) == 2 && kept[0] == "/**" && strings.TrimSpace(kept[1]) == "*/" {
		return ""
	}
	return doctrineGeneratedRegex.ReplaceAllString(strings.Join(kept, "\n"), "")
}

func equalAny(got, want any) bool {
	if g, ok := got.([]string); ok {
		return slices.Equal(g, want.([]string))
	}
	return got == want
}
